					slog.Int64("creator_id", int64(reaction.CreatorID)),
					slog.String("content_id", reaction.ContentID),
				)
				continue
			}
			return nil, err
		}
		reactionMessages = append(reactionMessages, reactionMessage)
	}
	return reactionMessages, nil
}

